#include "stdlib/lapack/base/dpbtf2.h"
#include "dpbtf2_private.h"

/**
* Computes a band Cholesky factorization.
*
* @param order  storage layout
* @param uplo   stored triangle
* @param N      number of dense rows and columns
* @param KD     number of stored off-diagonals
* @param AB     compact band input/output
* @param LDAB   leading dimension of the compact view
* @return       INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dpbtf2)( const LAPACK_LAYOUT order, const LAPACK_UPLO uplo, const LAPACK_INT N, const LAPACK_INT KD, double *AB, const LAPACK_INT LDAB ) {
	LAPACK_INT info;
	LAPACK_INT stride1;
	LAPACK_INT stride2;
	intmax_t first;
	intmax_t last;

	if ( order != LAPACK_ROW_MAJOR && order != LAPACK_COL_MAJOR ) return -1;
	info = dpbtf2_dimensions( 1, uplo, N, KD );
	if ( info != 0 ) return info;
	if ( ( order == LAPACK_COL_MAJOR && LDAB < (intmax_t)KD+1 ) || ( order == LAPACK_ROW_MAJOR && ( LDAB < 1 || LDAB < N ) ) ) return -6;
	if ( N == 0 ) return 0;
	if ( N == dpbtf2_lapack_max() ) return -3;
	stride1 = order == LAPACK_COL_MAJOR ? 1 : LDAB;
	stride2 = order == LAPACK_COL_MAJOR ? LDAB : 1;
	info = dpbtf2_geometry( (intmax_t)KD+1, N, stride1, stride2, 0, &first, &last );
	if ( info != 0 ) return -6;
	if ( dpbtf2_helpers_valid( uplo, N, KD, stride1, stride2 ) != 0 ) return -6;
	if ( !dpbtf2_envelope_valid( AB, first, last ) ) return -5;
	return API_SUFFIX(c_dpbtf2_ndarray)( uplo, N, KD, AB, stride1, stride2, 0 );
}
